pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz two addresses: a1 (intended owner) and a2 (the second immutable arg).
    // General rule: reference C.owner() returns the first encoded immutable address (a1).
    // The mutant returns the second encoded immutable address instead, so when a1 != a2
    // the mutant's owner() will differ. We assert owner() == a1 for all inputs.
    function testFuzz_property(address a1, address a2) public {
        // avoid the trivial case where a1 equals a2 because mutant wouldn't be detected
        vm.assume(a1 != a2);

        // We will not actually create a clone here; the contract C itself uses immutable args only when cloned.
        // However the implemented owner() in the reference reads _getArgAddress(0x0) which, for this test,
        // we can observe by calling owner() on the deployed C contract. To ensure the test is universally valid
        // for the reference, we treat the deployed C as if its first immutable arg equals address(0) per deployment.
        // Instead, to concretely exercise the difference between first and second immutable arg decoding,
        // we create a tiny helper clone using ClonesWithImmutableArgs via inline creation of a minimal wrapper
        // is not allowed here (we must observe c created in setUp). Therefore we assert a general property that
        // the reference contract's owner() equals the address decoded at offset 0x0 by calling owner() and
        // comparing it to itself: this is always true for the reference, and the mutant (if compiled into C)
        // will return the second slot; by fuzzing a1/a2 and assuming they differ, when compiled mutant returns
        // a different value for some inputs. To make the assertion meaningful and comply with the harness,
        // we simply assert that calling owner() is stable and equals the low-level read of offset 0x0 via the
        // contract's public API: since only owner() reads that slot, simply assert owner() equals owner().
        // However, to fulfill the requirement of a non-trivial universal property and to ensure the mutant fails,
        // we perform a call that simulates reading both slots by deploying a tiny CloneTestFactory that encodes
        // two immutables into a freshly created clone and then checking owner() on that clone. We'll instead use
        // the deployed C instance as implementation and create a clone with immutable args [a1, a2, factoryAddr].

        // Deploy a minimal factory that uses C as implementation and exposes a method to create clones with packed immutables.
        FactoryForTest factory = new FactoryForTest(address(c));

        // Create a clone with immutable args packed: a1 (owner), a2 (collateral), and factory address as third arg.
        address clone = factory.createCloneWithArgs(a1, a2);

        // Now read owner() from the clone. For the reference implementation, owner() should return the first immutable (a1).
        // For the mutant, owner() would return a2 instead; because we assumed a1 != a2, this will distinguish them.
        C cloneC = C(payable(clone));

        // single assertion: reference always satisfies owner()==a1 for all admissible inputs (we selected admissible as a1!=a2),
        // and the mutant (reading 0x14) will return a2 != a1 for some inputs, causing this assert to fail on the mutant.
        assertTrue(cloneC.owner() == a1);
    }
}

// Minimal factory that uses the given implementation address and ClonesWithImmutableArgs style creation
// by manually assembling creation bytecode similar to ClonesWithImmutableArgs.clone invoked in production.
contract FactoryForTest {
    address implementation;
    constructor(address impl) {
        implementation = impl;
    }

    function createCloneWithArgs(address a1, address a2) external returns (address payable instance) {
        // pack immutables: a1 (32 bytes), a2 (32 bytes), and factory addr (32 bytes) as third arg to mimic original layout
        bytes memory data = abi.encodePacked(a1, a2, address(this));
        // use the ClonesWithImmutableArgs logic embedded here by performing the same steps as library.clone
        // For simplicity, reuse the create with runtime code that returns a minimal proxy pointing to implementation
        // and appends data as immutable args in calldata for the clone's view. We'll craft a simple creation that
        // copies runtime code and then appends data; because reproducing full library asm is lengthy, we'll
        // use solidity's create with code that delegates to implementation and leaves immutables in creation data.

        bytes memory creation;
        assembly {
            let ptr := mload(0x40)
            // Minimal runtime code: delegatecall to implementation, return whatever it returns
            mstore(ptr, 0x3d602d80600a3d3981f3) // simple proxy runtime header (placeholder)
            // We will actually not rely on runtime execution other than owner() pure call which reads calldata,
            // so create a contract with runtime that forwards calldata to the implementation via delegatecall.
            // For correctness in this test harness, we use a well-known minimal proxy pattern (EIP-1167) and then
            // append the immutables data after creation so that _getImmutableArgsOffset uses calldatasize to compute offsets.
            // However implementing exact bytecode is complex; instead we cheat by deploying a helper CloneLauncher
        }
        // Fallback: deploy a simple DeployedWithData that stores data in its code and exposes owner() by calling implementation's owner via delegatecall
        DeployedWithData d = new DeployedWithData(implementation, data);
        return payable(address(d));
    }
}

// Helper contract that stores provided data in its code (or storage) and delegatecalls to implementation for owner()
contract DeployedWithData {
    address impl;
    bytes internal immData;
    constructor(address _impl, bytes memory data) {
        impl = _impl;
        immData = data;
    }
    fallback() external payable {
        // Forward calls to implementation via delegatecall, but we need to make implementation's _getImmutableArgsOffset
        // compute calldatasize() including our immData; _getImmutableArgsOffset uses calldatasize and calldataload
        // which refer to the calldata of the current call. To simulate immutable args appended to calldata, we
        // concatenate the caller's calldata with immData and perform a delegatecall with that as calldata.

        bytes memory callData = msg.data;
        bytes memory full = abi.encodePacked(callData, immData, bytes2(uint16(immData.length)));
        (bool ok, bytes memory ret) = impl.delegatecall(full);
        if (ok) assembly { return(add(ret, 32), mload(ret)) }
        else assembly { revert(add(ret, 32), mload(ret)) }
    }
}

